""" Modified to calculate average quality score of a sequence """
def qual_stat(qstr: Any) -> object {
    q30_sum = 0;
    q30_seq = 0;
    for q in qstr {
        qual = q - 33;
        q30_sum += qual;
    }
    q30_seq = q30_sum / len(qstr);
    return q30_seq;
}

"""Modeled after the cubic y = (x - 1)^3 + 1"""
def cubic_ease_out(p: Any) -> object {
    f = p - 1;
    return ((f * f * f) + 1);
}
